import{_ as t,o as s,c as n,a5 as r}from"./chunks/framework.PLGyiLjE.js";const c=JSON.parse('{"title":"Settings worth knowing","description":"","frontmatter":{},"headers":[],"relativePath":"guides/settings.md","filePath":"guides/settings.md"}'),e={name:"guides/settings.md"};function a(i,o,g,l,h,u){return s(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="settings-worth-knowing" tabindex="-1">Settings worth knowing <a class="header-anchor" href="#settings-worth-knowing" aria-label="Permalink to &quot;Settings worth knowing&quot;">​</a></h1><p>Open <strong>More → Settings</strong>. There are four tabs down the side: <strong>Sound</strong>, <strong>Display</strong>, <strong>Controls</strong> and <strong>Language</strong>. Your choices are saved to your account.</p><h2 id="sound" tabindex="-1">Sound <a class="header-anchor" href="#sound" aria-label="Permalink to &quot;Sound&quot;">​</a></h2><ul><li>Sliders for <strong>Music</strong>, <strong>Combat</strong>, <strong>Characters</strong>, <strong>Master</strong>, <strong>Ambience</strong> and <strong>Important alerts</strong>, plus <strong>Mute all</strong>.</li><li><strong>Camera shake</strong> and <strong>Show my damage numbers</strong> on or off.</li><li><strong>Graphics: Low or High.</strong> Low means fewer, lighter effects for a smoother game.</li></ul><h2 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h2><ul><li><strong>HUD size</strong>, <strong>UI scale</strong>, <strong>Game text size</strong> (or <strong>Follow Roblox text size</strong>) and <strong>HUD opacity</strong>.</li><li><strong>Soften scenery</strong> dims busy backgrounds behind the path. Easier on the eyes.</li><li>On touch screens: <strong>Control size</strong>, <strong>Left-handed controls</strong> and <strong>Follow-the-thumb stick</strong> (touch anywhere on the left to walk).</li><li><strong>Reduce motion &amp; flashing:</strong> no blinking, pulsing or sparkles.</li><li><strong>Combat clarity</strong> calms busy fights. Your HP and boss warnings always show.</li><li><strong>Colour vision</strong> and <strong>Performance mode</strong>.</li><li><strong>Hold Attack to repeat</strong> (on by default).</li><li><strong>Auto-potion</strong> uses a ready heal from quick slots 1–4 when your HP drops below the level you pick in <strong>Use below HP</strong>. Most players use 35%.</li></ul><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><ul><li><strong>Keys:</strong> Arrow keys or WASD. 1–4 use items in both.</li><li><strong>Keyboard hotkeys:</strong> rebind your eight action keys.</li><li><strong>Arrange controls</strong> (touch): move and resize buttons or whole groups. Phone controls are new and may change.</li></ul><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>English, Español or Português (or Automatic), plus the text size options.</p><p><strong>Found something confusing?</strong> Press <strong>Feedback</strong> in <strong>More</strong>. It goes straight to the team.</p>',11)])])}const m=t(e,[["render",a]]);export{c as __pageData,m as default};
